var s = Trim($feature.Planning_Status);
// Normalize dash characters to avoid mismatch (–, — vs -)
s = Replace(s, "–", "-");
s = Replace(s, "—", "-");
// 1) If status is Completed / Scheduled, show it as-is
if (s == "Completed") {
 return "Completed";
}
if (s == "Scheduled") {
 return "In progress";
}
// 3) Otherwise show nothing
return Null;

